def set_up_central_warehouse(apps, schema_editor):
    """สาขาศรีณรงค์ is the central warehouse; บุ่งหวาย is added as a store. Existing databases keep their stock."""
    Branch = apps.get_model("inventory", "Branch")
    Branch.objects.filter(code="srinarong").update(kind="central")
    Branch.objects.get_or_create(code="bungwai", defaults={"name": "สาขาบุ่งหวาย", "kind": "store", "sort_order": 2})


